// PRO-015 criteria 2 and 3 on signed tokens: an unknown `restrict` value is ignored, a `restrict`
// that is not an array is refused, and `wfp`, `amr` and `auth_time` are recorded as given without
// being treated as identity proof (FRW-038, FRW-040). Every key here is generated by the test.
// Lane U-PRO-001-017.
import { randomUUID } from 'node:crypto';
import { uuid7 } from '@docedit/model';
import { beforeEach, describe, expect, it } from 'vitest';
import { signJws } from '../../src/control-plane/jwt.ts';
import { MemoryTenantRegistry } from '../../src/control-plane/tenants.ts';
import { signingKey, TokenService } from '../../src/control-plane/tokens.ts';
import { MemoryUserDirectory } from '../../src/control-plane/users.ts';
import { hostKey } from './support.ts';

const SERVICE = 'https://docs.example.test';

describe('restrict, wfp, amr and auth_time on user tokens (PRO-015 criteria 2 and 3)', () => {
  let now = Date.now();
  let tenant: string;
  let tokens: TokenService;
  const host = hostKey('ES256');
  const doc = uuid7();

  beforeEach(async () => {
    now = Date.now();
    tenant = randomUUID();
    const registry = new MemoryTenantRegistry(() => now);
    await registry.putTenant(tenant, 't');
    await registry.addKey(tenant, { kid: host.kid, use: 'user', alg: 'ES256', jwk: host.jwk });
    tokens = new TokenService({
      registry,
      users: new MemoryUserDirectory(),
      serviceId: SERVICE,
      signing: signingKey(undefined, 'svc'),
      now: () => now,
    });
  });

  const sign = (claims: Record<string, unknown> = {}) => {
    const iat = Math.floor(now / 1000);
    return signJws(
      { alg: host.alg, typ: 'JWT', kid: host.kid },
      {
        iss: 'host',
        aud: SERVICE,
        iat,
        exp: iat + 300,
        jti: uuid7(),
        tid: tenant,
        sub: 'u-1',
        docs: { [doc]: 'editor' },
        ...claims,
      },
      host.privateKey,
    );
  };

  it('keeps the known restrictions in token order, once each, and ignores unknown values (criterion 2)', async () => {
    const id = await tokens.verifyUser(
      sign({ restrict: ['no-print', 'x-unknown', 'no-export', 'no-print', 7] }),
    );
    expect(id.restrict).toEqual(['no-print', 'no-export']);
  });

  it('refuses a restrict claim that is not an array (criterion 2 does not cover malformed claims)', async () => {
    await expect(tokens.verifyUser(sign({ restrict: 'no-export' }))).rejects.toMatchObject({
      code: 'unauthenticated',
    });
  });

  it('gives no restrictions when the claim is absent or holds only unknown values', async () => {
    expect((await tokens.verifyUser(sign())).restrict).toEqual([]);
    expect((await tokens.verifyUser(sign({ restrict: ['nope'] }))).restrict).toEqual([]);
  });

  it('records wfp, amr and auth_time as given and does not change the identity from them (criterion 3)', async () => {
    const id = await tokens.verifyUser(
      sign({ wfp: 'p-legal-1', amr: ['pwd', 'otp'], auth_time: 1_700_000_000 }),
    );
    expect(id.asserted).toEqual({
      wfp: 'p-legal-1',
      amr: ['pwd', 'otp'],
      auth_time: 1_700_000_000,
    });
    // The identity and the role come from the same claims as without them.
    const bare = await tokens.verifyUser(sign());
    expect(id.connection).toEqual(bare.connection);
    expect(id.sub).toBe(bare.sub);
  });

  it('records only the well-typed assertions and omits the field when there are none (criterion 3)', async () => {
    const partial = await tokens.verifyUser(sign({ wfp: '', amr: 'pwd', auth_time: 'now' }));
    expect(partial.asserted).toBeUndefined();
    const some = await tokens.verifyUser(sign({ amr: ['hwk'] }));
    expect(some.asserted).toEqual({ amr: ['hwk'] });
    expect((await tokens.verifyUser(sign())).asserted).toBeUndefined();
  });
});
